content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: #f0f2f5;
  color: #333;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

.app-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: #ffffff;
  padding: 2rem;
  border-radius: 16px;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.1);
  max-width: 800px;
  width: 100%;
}

.header {
  text-align: center;
  margin-bottom: 1.5rem;
}

.header h1 {
  font-size: 1.8rem;
  margin-bottom: 0.5rem;
  color: #1a1a1a;
}

.header p {
  color: #666;
  font-size: 0.95rem;
}

.controls {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin: 1.5rem 0;
  background: #f8f9fa;
  padding: 0.75rem 1.5rem;
  border-radius: 8px;
  border: 1px solid #e9ecef;
}

.controls label {
  font-weight: 600;
  font-size: 0.9rem;
  color: #495057;
}

.select-wave {
  padding: 0.5rem 1rem;
  font-size: 0.95rem;
  border: 1px solid #ced4da;
  border-radius: 6px;
  background-color: #fff;
  color: #212529;
  cursor: pointer;
  outline: none;
  transition: border-color 0.2s;
}

.select-wave:focus {
  border-color: #4c6ef5;
  box-shadow: 0 0 0 3px rgba(76, 110, 245, 0.15);
}

.keyboard-container {
  display: flex;
  justify-content: center;
  overflow-x: auto;
  width: 100%;
  padding: 1rem 0;
}

.piano-keyboard {
  position: relative;
  display: flex;
  background: #212529;
  padding: 12px;
  border-radius: 8px;
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.2);
  user-select: none;
}

.white-key {
  position: relative;
  width: 50px;
  height: 200px;
  background: #ffffff;
  border: 1px solid #ccc;
  border-radius: 0 0 6px 6px;
  margin-right: 2px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: center;
  padding-bottom: 15px;
  transition: background-color 0.1s, transform 0.05s;
  box-shadow: inset 0 -5px 10px rgba(0, 0, 0, 0.1);
}

.white-key:last-child {
  margin-right: 0;
}

.white-key.pressed {
  background: #e2e6ea;
  box-shadow: inset 0 2px 5px rgba(0, 0, 0, 0.2);
  transform: translateY(2px);
}

.black-key {
  position: absolute;
  width: 32px;
  height: 120px;
  background: #343a40;
  border-radius: 0 0 4px 4px;
  z-index: 2;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: center;
  padding-bottom: 10px;
  transition: background-color 0.1s, transform 0.05s;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3);
}

.black-key.pressed {
  background: #1a1e21;
  transform: translateY(2px);
  box-shadow: 0 2px 3px rgba(0, 0, 0, 0.3);
}

.key-label {
  font-size: 0.75rem;
  font-weight: bold;
  pointer-events: none;
}

.white-key .key-label {
  color: #495057;
}

.black-key .key-label {
  color: #f8f9fa;
  font-size: 0.65rem;
}

.footer-note {
  margin-top: 1.5rem;
  font-size: 0.85rem;
  color: #868e96;
  text-align: center;
}

export type WaveType = 'sine' | 'square' | 'sawtooth' | 'triangle';

export interface NoteKey {
  id: string;
  label: string;
  note: string;
  frequency: number;
  isBlack: boolean;
}

import { FC, CSSProperties } from 'react';
import { NoteKey } from '../types';

interface PianoKeyProps {
  keyData: NoteKey;
  isPressed: boolean;
  onPlay: (key: NoteKey) => void;
  style?: CSSProperties;
}

export const PianoKey: FC<PianoKeyProps> = ({ keyData, isPressed, onPlay, style }) => {
  const className = `${keyData.isBlack ? 'black-key' : 'white-key'} ${isPressed ? 'pressed' : ''}`;

  return (
    <div
      className={className}
      style={style}
      onPointerDown={(e) => {
        e.preventDefault();
        onPlay(keyData);
      }}
    >
      <span className="key-label">{keyData.label}</span>
    </div>
  );
};

export default PianoKey;

import { FC, useState, useRef, useCallback, useEffect } from 'react';
import { NoteKey, WaveType } from './types';
import { PianoKey } from './components/PianoKey';

const KEYS: NoteKey[] = [
  { id: 'C4', label: 'A', note: 'C4', frequency: 261.63, isBlack: false },
  { id: 'Db4', label: 'W', note: 'C#4', frequency: 277.18, isBlack: true },
  { id: 'D4', label: 'S', note: 'D4', frequency: 293.66, isBlack: false },
  { id: 'Eb4', label: 'E', note: 'D#4', frequency: 311.13, isBlack: true },
  { id: 'E4', label: 'D', note: 'E4', frequency: 329.63, isBlack: false },
  { id: 'F4', label: 'F', note: 'F4', frequency: 349.23, isBlack: false },
  { id: 'Gb4', label: 'T', note: 'F#4', frequency: 369.99, isBlack: true },
  { id: 'G4', label: 'G', note: 'G4', frequency: 392.00, isBlack: false },
  { id: 'Ab4', label: 'Y', note: 'G#4', frequency: 415.30, isBlack: true },
  { id: 'A4', label: 'H', note: 'A4', frequency: 440.00, isBlack: false },
  { id: 'Bb4', label: 'U', note: 'A#4', frequency: 466.16, isBlack: true },
  { id: 'B4', label: 'J', note: 'B4', frequency: 493.88, isBlack: false },
  { id: 'C5', label: 'K', note: 'C5', frequency: 523.25, isBlack: false },
];

export const App: FC = () => {
  const [waveType, setWaveType] = useState<WaveType>('sine');
  const [pressedKeyIds, setPressedKeyIds] = useState<string[]>([]);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const playNote = useCallback((key: NoteKey) => {
    if (!audioCtxRef.current) {
      const AudioCtx = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      audioCtxRef.current = new AudioCtx();
    }
    const ctx = audioCtxRef.current;
    if (ctx.state === 'suspended') {
      ctx.resume();
    }

    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.type = waveType;
    osc.frequency.setValueAtTime(key.frequency, ctx.currentTime);

    gain.gain.setValueAtTime(0.2, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.8);

    osc.connect(gain);
    gain.connect(ctx.destination);

    osc.start();
    osc.stop(ctx.currentTime + 0.8);

    setPressedKeyIds((prev) => [...prev, key.id]);
    setTimeout(() => {
      setPressedKeyIds((prev) => prev.filter((id) => id !== key.id));
    }, 200);
  }, [waveType]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.repeat) return;
      const targetKey = KEYS.find((k) => k.label.toLowerCase() === e.key.toLowerCase());
      if (targetKey) {
        playNote(targetKey);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [playNote]);

  const getBlackKeyLeft = (index: number): string => {
    let whiteCount = 0;
    for (let i = 0; i < index; i++) {
      if (!KEYS[i].isBlack) {
        whiteCount++;
      }
    }
    const position = whiteCount * 52 - 18;
    return `${position}px`;
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1>Webブラウザピアノ</h1>
        <p>1オクターブの鍵盤をクリックまたはタップして演奏しましょう</p>
      </header>

      <div className="controls">
        <label htmlFor="wave-select">音色 (波形):</label>
        <select
          id="wave-select"
          className="select-wave"
          value={waveType}
          onChange={(e) => setWaveType(e.target.value as WaveType)}
        >
          <option value="sine">サイン波 (Sine)</option>
          <option value="square">矩形波 (Square)</option>
          <option value="sawtooth">のこぎり波 (Sawtooth)</option>
          <option value="triangle">三角波 (Triangle)</option>
        </select>
      </div>

      <div className="keyboard-container">
        <div className="piano-keyboard">
          {KEYS.map((key, index) => {
            const isPressed = pressedKeyIds.includes(key.id);
            const style = key.isBlack ? { left: getBlackKeyLeft(index) } : undefined;

            return (
              <PianoKey
                key={key.id}
                keyData={key}
                isPressed={isPressed}
                onPlay={playNote}
                style={style}
              />
            );
          })}
        </div>
      </div>

      <footer className="footer-note">
        Web Audio API を使用したリアルタイム音声合成
      </footer>
    </div>
  );
};

export default App;
